/* nodes details for region "math", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("math.nodes",{"nodes":{
"area-model-multiplication":{"description":{"zh":"a × b 就是 a 行 b 列方格的总数，也就是长方形的面积：转个方向面积不变（交换律），切一刀分成两块再相加（分配律），两位数乘法的竖式就是把一块地切成四块分别算。","en":"a × b is the number of squares in a rows of b columns — the area of a rectangle: turning it round leaves the area unchanged (the commutative law), cutting it in two and adding the pieces is the distributive law, and the written method for two-digit multiplication computes the four pieces of one cut-up plot."},"formula":"a(b + c) = ab + ac","source":"../math/arithmetic/area-model/#step1","lessons":[{"slug":"area-model","step":1,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["乘法的意义","面积模型","乘法分配律","乘法交换律","竖式乘法为什么是对的","因数对","点阵","长方形面积"],"en":["what multiplication means","area model","distributive law","commutative law","why long multiplication works","factor pairs","dot array","area of a rectangle"]}},
"chicken-rabbit":{"description":{"zh":"先假设全是一种，差额除以每换一个的变化量，得到另一种的个数。仅适用于两种对象、每个数量固定且为整数的题。","en":"Assume everything is one kind; the gap divided by the change per swap gives the count of the other kind. For two kinds with fixed whole-number amounts."},"formula":"r = (F − 2H) / 2","source":"../math/arithmetic/chicken-rabbit/#step2","lessons":[{"slug":"chicken-rabbit","step":2,"category":"math","stage":"primary","primary":true}]},
"circle-intro":{"description":{"zh":"圆是到圆心等距的点；周长与直径之比是固定的 π，面积 π r²。π 用多边形逼近展示，假设理想平面圆。","en":"A circle is the set of points at a fixed distance from the centre; circumference over diameter is the constant π and area is πr². π is shown by polygon approximation on an ideal plane circle."},"formula":"C = πd, A = πr²","source":"../math/geometry/circle-intro/#step3","lessons":[{"slug":"circle-intro","step":3,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["圆周率","圆周率π","π","圆周率是怎么来的","为什么圆周率是3.14","周长公式"],"en":["pi","what is pi","why is pi 3.14","circumference"]}},
"division-remainder":{"description":{"zh":"把一堆东西平均分，分到每人再也分不到一份时停下，剩下的就是余数，所以余数一定比除数小；“被除数 = 除数 × 商 + 余数”是这本账，星期几的循环也只看余数。","en":"Share things out equally until there is not enough left to give everyone one more, and what remains is the remainder — so it is always smaller than the divisor; “dividend = divisor × quotient + remainder” is the ledger, and cycles like the days of the week depend only on the remainder."},"formula":"a = b·q + r,  0 ≤ r < b","source":"../math/arithmetic/division-remainder/#step1","lessons":[{"slug":"division-remainder","step":1,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["有余数的除法","余数为什么比除数小","商和余数","100 天后是星期几","取余 取模","除法验算"],"en":["division with remainder","why is the remainder smaller than the divisor","quotient and remainder","what weekday is it 100 days from now","modulo","checking a division"]}},
"equation-balance":{"description":{"zh":"等号像一架平衡天平的指针：等式两边一样重，只要对两边同时加、减、乘、除同一个数（不除以 0），天平就保持平衡；解方程就是用这一招把未知数 x 单独留在一边。","en":"The equals sign is like the needle of a balanced scale: both sides weigh the same, and adding, subtracting, multiplying or dividing both sides by the same number (never dividing by 0) keeps it balanced; solving an equation means using that one move to leave the unknown x alone on one side."},"formula":"a = b ⇒ a + c = b + c","source":"../math/algebra/equation-scale/#step1","lessons":[{"slug":"equation-scale","step":1,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["解方程","等式的性质","移项","一元一次方程","未知数 x","等号是什么意思","天平法解方程"],"en":["solving equations","properties of equality","moving a term across the equals sign","linear equation in one unknown","the unknown x","what does the equals sign mean","balance method"]}},
"fractions":{"description":{"zh":"分数是一个数，不是上下摆着的两个数：分母说把整体平均切成几份，分子说取了其中几份；1/2、2/4、4/8 是同一个数换了写法，分母不同的分数要先通分才能比大小和相加。","en":"A fraction is one number, not two stacked numbers: the denominator says how many equal parts the whole is cut into and the numerator how many are taken; 1/2, 2/4 and 4/8 are one number written differently, and fractions with different denominators must share a common denominator before comparing or adding."},"formula":"a/b = (a·k)/(b·k)","source":"../math/arithmetic/fractions/#step1","lessons":[{"slug":"fractions","step":1,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["分数","分子 分母","等值分数","通分","约分","假分数 带分数","1/2 + 1/3 为什么不等于 2/5","分数比大小"],"en":["fraction","numerator and denominator","equivalent fractions","common denominator","simplifying a fraction","improper fraction and mixed number","why is 1/2 + 1/3 not 2/5","comparing fractions"]}},
"intervals-fences":{"description":{"zh":"棵数与段数相差 +1、0 或 −1，取决于两端是否种；锯木头、楼梯同理。假设间隔相等且整除总长。","en":"Trees and gaps differ by +1, 0 or −1 depending on whether the ends are planted; sawing and stairs follow the same count. Assumes equal spacing that divides the length."},"formula":"trees = length ÷ spacing + 1 (both ends)","source":"../math/arithmetic/intervals-fences/#step2","lessons":[{"slug":"intervals-fences","step":2,"category":"math","stage":"primary","primary":true}]},
"negative-numbers":{"description":{"zh":"负数记录“在基准的另一边、差多少”：温度计上的零下、电梯里的 B1、数轴上 0 的左边都是它；越往左越小，所以 −3 比 −7 大，加法向右走、减法向左走。","en":"A negative number records “on the other side of the reference point, and by how much”: below zero on a thermometer, B1 in a lift, left of 0 on the number line; further left means smaller, so −3 is greater than −7, and adding steps right while subtracting steps left."},"source":"../math/arithmetic/negative-numbers/#step0","lessons":[{"slug":"negative-numbers","step":0,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["负数","零下几度怎么写","−3 和 −7 哪个大","正数和负数","数轴","负数加减法","地下一层 B1"],"en":["negative numbers","how to write a below-zero temperature","which is bigger, −3 or −7","positive and negative numbers","number line","adding and subtracting negative numbers","basement level B1"]}},
"patterns-sequences":{"description":{"zh":"用火柴棒链数出前几项，求相邻总数的增量；增量不变时总数 = 增量×n + 起头。仅适用于相邻图形共用一条边的单排摆法。","en":"Count the first few matchstick figures and find the step between totals; for a constant step, total = step × n + starter. Holds only for single chains whose neighbours share one side."},"formula":"a(n) = d·n + 1","source":"../math/algebra/patterns-sequences/#step2","lessons":[{"slug":"patterns-sequences","step":2,"category":"math","stage":"primary","primary":true}]},
"perimeter-vs-area":{"description":{"zh":"周长是绕图形一圈的长度，面积是图形里面铺满要多少块方格；同一根 24 米的绳子能围出 11 到 36 平方米不等的长方形，越接近正方形面积越大，所以周长相同不代表面积相同。","en":"Perimeter is the length around a shape and area is how many squares fill its inside; the same 24-metre rope can enclose rectangles of anywhere from 11 to 36 square metres, larger the closer to a square, so equal perimeters do not mean equal areas."},"formula":"P = 2(a + b),  S = a·b","source":"../math/geometry/perimeter-area/#step1","lessons":[{"slug":"perimeter-area","step":1,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["周长和面积的区别","周长一样面积一样吗","围成什么形状面积最大","长方形周长公式","篱笆围地","周长"],"en":["perimeter vs area","same perimeter, same area?","which shape encloses the most area","perimeter of a rectangle","fencing problem","perimeter"]}},
"place-value":{"description":{"zh":"十进制位值：同一数字每左移一位大 10 倍，满十进一，0 占位。仅涉及十进制整数（≤9999 的计数器）。","en":"Base-ten place value: a digit is worth 10 times more one place left, ten makes one, 0 holds a place. Whole numbers only, on a frame up to 9999."},"formula":"n = Σ dᵢ·10ⁱ","source":"../math/arithmetic/place-value/#step2","lessons":[{"slug":"place-value","step":2,"category":"math","stage":"primary","primary":true}],"note":"No existing atlas node (math group) fits; edge points to sibling page patterns-sequences (batch b1). exp-log page has no atlas node yet."},
"symmetry":{"description":{"zh":"沿一条线对折、两边完全重合，这条线就是对称轴；绕中心转过某个角度又和原来重合，就是旋转对称——一个靠翻、一个靠转：正方形有 4 条对称轴，平行四边形一条也没有，却转半圈就重合。","en":"If folding along a line makes the two halves match exactly, that line is an axis of symmetry; if turning about the centre by some angle brings a shape back onto itself, it has rotational symmetry — one is a flip, the other a turn: a square has 4 axes, while a parallelogram has none yet matches itself after half a turn."},"source":"../math/geometry/symmetry-rotation/#step0","lessons":[{"slug":"symmetry-rotation","step":0,"category":"math","stage":"primary","primary":true}],"aliases":{"zh":["对称轴","轴对称图形","旋转对称","中心对称","正方形有几条对称轴","万花筒原理","镜像"],"en":["axis of symmetry","line-symmetric shape","rotational symmetry","point symmetry","how many lines of symmetry does a square have","how a kaleidoscope works","mirror image / reflection"]}},
"coordinate-plane":{"description":{"zh":"给平面定一个原点和互相垂直的两根数轴，每个点就有了一个先横后纵的地址 (x, y)：(3, 2) 和 (2, 3) 是两个不同的点，四个象限的符号由两根轴的正负拼成，这套地址是所有函数图像的地基。","en":"Fix an origin and two perpendicular number lines, and every point gets an address (x, y), across first then up: (3, 2) and (2, 3) are different points, the signs in the four quadrants come from the two axes, and this address system underlies every function graph."},"formula":"(x, y)","source":"../math/algebra/coordinate-plane/#step2","lessons":[{"slug":"coordinate-plane","step":2,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["坐标系","直角坐标系","象限","横坐标 纵坐标","怎么读坐标","原点","两点间的距离和中点"],"en":["coordinate system","Cartesian coordinates","quadrants","x-coordinate and y-coordinate","how to read coordinates","origin","distance and midpoint between two points"]}},
"euclidean-algorithm":{"description":{"zh":"求两个数的最大公因数不必试遍所有因数：用大数除以小数取余数，再用除数除以余数，反复下去，最后一个非零余数就是最大公因数；最小公倍数等于两数之积除以它。","en":"To find the greatest common divisor of two numbers you need not try every factor: divide the larger by the smaller and keep the remainder, divide the divisor by that remainder, and repeat — the last nonzero remainder is the gcd, and the least common multiple is the product divided by it."},"formula":"gcd(a, b) = gcd(b, a mod b)","source":"../math/arithmetic/number-combinatorics/#step1","lessons":[{"slug":"number-combinatorics","step":1,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["最大公因数","最大公约数","最小公倍数","辗转相除法","欧几里得算法","怎么求最大公约数"],"en":["greatest common divisor","gcd","least common multiple","Euclidean algorithm","Euclid’s algorithm","how to find the gcd"]}},
"inequalities":{"description":{"zh":"一元一次不等式的解集是数轴上的一段；两边加减不变号，乘除负数要翻号。仅限 a·x+b<c（或≤）。","en":"The solution of a linear inequality is a stretch of the number line; adding or subtracting keeps the sign, multiplying or dividing by a negative flips it. Only a·x + b < c (or ≤)."},"formula":"a·x + b < c","source":"../math/algebra/inequalities/#step3","lessons":[{"slug":"inequalities","step":3,"category":"math","stage":"junior","primary":true}]},
"inscribed-angle":{"description":{"zh":"从圆周上一点看一段弧，张开的角（圆周角）永远是从圆心看同一段弧的角（圆心角）的一半，而且在同一段弧上站在哪里都一样；所以直径所对的圆周角一定是直角。","en":"Seen from a point on the circle, an arc opens an angle (the inscribed angle) that is always exactly half the angle it opens at the centre (the central angle), wherever on the same arc you stand; so an angle that subtends a diameter is always a right angle."},"formula":"∠APB = ½ ∠AOB","source":"../math/geometry/circle-angles/#step1","lessons":[{"slug":"circle-angles","step":1,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["圆周角","圆心角","圆周角定理","泰勒斯定理","直径所对的圆周角是直角","同弧所对的圆周角相等"],"en":["inscribed angle","central angle","inscribed angle theorem","Thales’ theorem","the angle in a semicircle is a right angle","angles on the same arc are equal"]}},
"inverse-proportion":{"description":{"zh":"乘积 x·y = k 不变的关系，图像是不与坐标轴相交的双曲线。只展示 k>0、x>0 的一支。","en":"A relation with constant product x·y = k graphs as a hyperbola that never meets the axes. Only the k > 0, x > 0 branch is shown."},"formula":"y = k / x","source":"../math/algebra/inverse-proportion/#step2","lessons":[{"slug":"inverse-proportion","step":2,"category":"math","stage":"junior","primary":true}]},
"parabola":{"description":{"zh":"投篮的弧线就是抛物线：y = ax² 里 a 决定开口方向和胖瘦，写成顶点式 y = a(x − h)² + k 后顶点 (h, k) 和对称轴 x = h 一眼可读；图像与 x 轴有两个、一个或没有交点，就是 y = 0 有两个、一个或没有实数解。","en":"A basketball’s arc is a parabola: in y = ax², a sets the opening direction and width; in vertex form y = a(x − h)² + k the vertex (h, k) and the axis x = h can be read off directly; crossing the x-axis twice, once or not at all means y = 0 has two, one or no real solutions."},"formula":"y = a(x − h)² + k","source":"../math/algebra/parabola/#step2","lessons":[{"slug":"parabola","step":2,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["抛物线","二次函数","顶点式","二次函数图像","开口方向","一元二次方程的根","判别式","二次函数 抛物线"],"en":["parabola","quadratic function","vertex form","graph of a quadratic","which way a parabola opens","roots of a quadratic equation","discriminant"]}},
"polygon-angles":{"description":{"zh":"n 边形内角和 (n−2)×180°，外角和 360°，对平面简单多边形（含凹）成立；曲面上不成立。","en":"The interior angles of an n-gon add to (n−2)×180° and the exterior angles to 360° for simple plane polygons, convex or concave; not on curved surfaces."},"formula":"Σ interior = (n − 2) · 180°","source":"../math/geometry/polygon-angles/#step2","lessons":[{"slug":"polygon-angles","step":2,"category":"math","stage":"junior","primary":true}]},
"prime-factorization":{"description":{"zh":"每个大于 1 的整数都能唯一地写成质数幂的乘积，就像它的骨架；指数还直接告诉你它有多少个正因数，比如 12 = 2²·3 有 (2+1)(1+1) = 6 个。","en":"Every whole number greater than 1 can be written in exactly one way as a product of prime powers — its skeleton; the exponents even tell how many divisors it has: 12 = 2²·3 has (2+1)(1+1) = 6."},"formula":"n = p₁^a₁ · p₂^a₂ ⋯","source":"../math/arithmetic/number-combinatorics/#step0","lessons":[{"slug":"number-combinatorics","step":0,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["质数","素数","分解质因数","算术基本定理","因数个数","合数"],"en":["prime number","prime","prime factorization","fundamental theorem of arithmetic","number of divisors","composite number"]}},
"pythagorean-theorem":{"description":{"zh":"直角三角形里两条直角边的平方和等于斜边的平方：用面积看，挂在两条直角边上的两个小正方形正好装满挂在斜边上的大正方形；反过来，三边满足这个等式的三角形一定有直角。","en":"In a right triangle the squares on the two legs add up to the square on the hypotenuse: seen as areas, the two small squares on the legs exactly fill the large square on the hypotenuse; conversely, a triangle whose sides satisfy the equation must have a right angle."},"formula":"a² + b² = c²","source":"../math/geometry/pythagoras/#step1","lessons":[{"slug":"pythagoras","step":1,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["勾股定理","毕达哥拉斯定理","商高定理","勾三股四弦五","勾股数","怎么求斜边","勾股定理逆定理","勾股定律"],"en":["Pythagorean theorem","Pythagoras’ theorem","Gougu theorem","3-4-5 triangle","Pythagorean triples","how to find the hypotenuse","converse of the Pythagorean theorem","pythagorus theorem"]}},
"real-number-line":{"description":{"zh":"单位正方形的对角线给出 √2 在数轴上的位置；它不能写成分数，小数不结束不循环，但可二分逼近。小数位由精确整数运算得到。","en":"The unit square's diagonal places √2 on the number line; it is not a fraction, its decimals neither stop nor repeat, yet bisection closes in on it. Digits come from exact integer arithmetic."},"formula":"√2 = 1.41421356…","source":"../math/arithmetic/real-number-line/#step2","lessons":[{"slug":"real-number-line","step":2,"category":"math","stage":"junior","primary":true}]},
"similarity-scaling":{"description":{"zh":"放大 k 倍：长度×k、面积×k²、体积×k³，形状和角度不变。巨人例子里的骨强与体重关系是示意简化。","en":"Enlarging by k multiplies lengths by k, areas by k² and volumes by k³ while shape and angles stay. The bone-strength example is an illustrative simplification."},"formula":"L × k, A × k², V × k³","source":"../math/geometry/similarity-scaling/#step2","lessons":[{"slug":"similarity-scaling","step":2,"category":"math","stage":"junior","primary":true}]},
"simultaneous-equations":{"description":{"zh":"两个一次方程的公共解是两条直线的交点，可用代入法或加减法算出；D=0 时无解或有无穷多解。仅限两个未知数。","en":"The common solution of two linear equations is the crossing of two lines, found by substitution or elimination; D = 0 means no solution or infinitely many. Two unknowns only."},"formula":"D = a₁b₂ − a₂b₁","source":"../math/algebra/simultaneous-equations/#step4","lessons":[{"slug":"simultaneous-equations","step":4,"category":"math","stage":"junior","primary":true}]},
"slope":{"description":{"zh":"非竖直直线的斜率是两点竖直坐标差除以水平坐标差，在同一直线上不变。一般单位为Y的单位除以X的单位；几何双轴同用长度单位时无量纲。","en":"A nonvertical line’s slope is vertical-coordinate change divided by horizontal-coordinate change and stays constant along the line. Its units are Y-units per X-unit; for two geometric length axes it is dimensionless."},"formula":"k = ΔY / ΔX, ΔX ≠ 0","source":"../math/algebra/linear-functions/#step2","lessons":[{"slug":"linear-functions","step":2,"category":"math","stage":"junior","primary":true}]},
"solid-geometry":{"description":{"zh":"数顶点、棱、面验证欧拉公式；放大 k 倍时表面积 ×k²、体积 ×k³；平面截立方体得到 3、4、5、6 边形，垂直于体对角线时从三角形到正六边形；切片累加得金字塔体积 1/3；用滚动法判断展开图能否折成立方体。正交投影的教学模型。","en":"Count vertices, edges and faces to check Euler’s formula; scaling by k multiplies surface area by k² and volume by k³; a plane cutting a cube gives 3-, 4-, 5- or 6-sided sections, from a triangle to a regular hexagon perpendicular to the space diagonal; slice sums give a pyramid’s volume as one third; a rolling test decides whether a net folds into a cube. An orthographic-projection teaching model."},"formula":"V − E + F = 2,  S ∝ k²,  V ∝ k³,  V_锥 = Sh/3","source":"../math/geometry/solid-geometry/#step2","lessons":[{"slug":"solid-geometry","step":2,"category":"math","stage":"junior","primary":true}],"note":"three-views is a page slug (b1 batch); integral is an atlas node.","aliases":{"zh":["欧拉多面体公式"],"en":["euler's polyhedron formula"]}},
"space-diagonal":{"description":{"zh":"长方体里连接最远两个角的斜线有多长？先在底面用一次勾股定理算出底面对角线 e，再把 e 和高 c 当作新直角三角形的两条直角边用第二次，得到 d = √(a² + b² + c²)。","en":"How long is the line joining a box’s two farthest corners? Use the Pythagorean theorem once on the base to get the base diagonal e, then again with e and the height c as the legs of a new right triangle, giving d = √(a² + b² + c²)."},"formula":"d = √(a² + b² + c²)","source":"../math/geometry/space-diagonal/#step1","lessons":[{"slug":"space-diagonal","step":1,"category":"math","stage":"junior","primary":true}],"aliases":{"zh":["体对角线","空间对角线","长方体对角线公式","箱子里能放多长的棍子","三维勾股定理","正方体对角线"],"en":["body diagonal","space diagonal","cuboid diagonal formula","longest stick that fits in a box","3D Pythagorean theorem","cube diagonal"]}},
"three-views":{"description":{"zh":"积木的主视图、左视图、俯视图三图对齐可还原立体；只有两个视图时可能有多种堆法。仅限 3×3 格、每格最高 3 块的方块堆。","en":"Front, left and top views lined up rebuild a block stack; two views alone can leave several stackings. Limited to 3×3 squares, up to 3 blocks each."},"formula":"faces = 6N − 2·(touching places)","source":"../math/geometry/three-views/#step3","lessons":[{"slug":"three-views","step":3,"category":"math","stage":"junior","primary":true}]},
"complex":{"description":{"zh":"把平面点写成复数后，乘以单位模复数就是旋转：乘以 i 是逆时针转 90°，连乘两次就是转 180°（即乘 −1）；实部和虚部就是这个点的两个坐标。","en":"Represent a plane point as a complex number, and multiplying by a unit-magnitude complex number rotates it: multiply by i to turn 90° counterclockwise, twice for 180° (that is, multiply by −1). Real and imaginary parts are the point's two coordinates."},"formula":"z = cos θ + i sin θ","source":"../math/algebra/complex-numbers/#step4","lessons":[{"slug":"complex-numbers","step":4,"category":"math","stage":"senior","primary":true}],"aliases":{"zh":["虚数","虚数i","i 是什么","欧拉公式"],"en":["imaginary number","imaginary numbers","what is i","square root of minus one","euler's formula"]}},
"compound-interest":{"description":{"zh":"利息也生利息使钱按倍数增长 A = P(1+r)ᵗ；计息再细也趋近上限 P·e^{rt}；翻倍时间约 72/r 年；把未来的钱折现 PV = FV/(1+r)ᵗ；定期存入与贷款是同一规则的两个方向。固定利率模型，不含通胀、税费，非投资建议。","en":"Interest that earns interest makes money grow by multiples, A = P(1+r)ᵗ; finer compounding approaches the ceiling P·e^{rt}; doubling takes about 72/r years; future money is discounted by PV = FV/(1+r)ᵗ; regular saving and loans are the same rule run in two directions. A fixed-rate model without inflation or fees, not financial advice."},"formula":"A = P(1 + r/m)^{mt} → P e^{rt}","source":"../investment/rates/compound-interest/#step1","lessons":[{"slug":"compound-interest","step":1,"category":"investment","stage":"senior","primary":true}],"note":"Edges use existing atlas nodes probability and montecarlo only where real; compound-interest is a new concept id.","aliases":{"zh":["利息","复利","利滚利","贴现","现值","现金流折现","贴现率","折现率"],"en":["interest","compounding","present value","discounting","discounted cash flow","discount rate","DCF","net present value"]}},
"conic-sections":{"description":{"zh":"圆、椭圆、抛物线、双曲线是平面切圆锥得到的一族曲线，可由到焦点与到准线的距离之比（离心率 e）统一定义；椭圆距离和、双曲线距离差为定值，二次方程的判别式 B² − 4AC 的符号决定类型。","en":"Circle, ellipse, parabola and hyperbola are the curves a plane cuts from a cone, unified by the ratio of distance to a focus over distance to a directrix (the eccentricity e); an ellipse has a constant distance sum, a hyperbola a constant difference, and the sign of the discriminant B² − 4AC of a quadratic equation sets the type."},"formula":"e = cos φ / cos α","source":"../math/geometry/conic-sections/#step1","lessons":[{"slug":"conic-sections","step":1,"category":"math","stage":"senior","primary":true}]},
"counting-permutations":{"description":{"zh":"分步相乘得到 n! 与 nPr = n!/(n−k)!；顺序不算数时除以 k! 得 nCr；等可能时概率 = 符合的方法数 ÷ 总方法数，生日问题是典型例子。独立选择、等可能结果的计数模型。","en":"Multiplying the choices at each step gives n! and nPr = n!/(n−k)!; dividing by k! when order does not matter gives nCr; with equally likely outcomes probability = favourable ways ÷ total ways, the birthday problem being a classic example. A counting model of independent choices and equally likely outcomes."},"formula":"nCr = n! / (k!(n−k)!)","source":"../probability/basics/counting-permutations/#step3","lessons":[{"slug":"counting-permutations","step":3,"category":"probability","stage":"senior","primary":true},{"slug":"number-combinatorics","step":2,"category":"math","stage":"junior","primary":false}],"note":"Edges: probability and bayes exist in the atlas; counting-permutations is a new concept id.","aliases":{"zh":["排列组合","排列和组合"],"en":["permutations and combinations"]}},
"derivative":{"description":{"zh":"可微函数的导数是瞬时变化率，也是切线斜率。位置对时间的导数是带方向的速度，速度对时间的导数是加速度。","en":"A derivative is an instantaneous rate and tangent slope. For position versus time it gives signed velocity; differentiating velocity gives acceleration."},"formula":"f′(t) = lim Δf/Δt","source":"../math/calculus/derivative/#step2","lessons":[{"slug":"derivative","step":2,"category":"math","stage":"senior","primary":true}],"aliases":{"zh":["什么是导数","瞬时速度","切线斜率","变化率"],"en":["what is a derivative","rate of change","instantaneous speed","slope of a tangent"]}},
"exp-log":{"description":{"zh":"指数是连乘的简写：2¹⁰ 就是 10 个 2 相乘；对数反过来问，多少次连乘才到这个数——log₂1024 = 10，因为 10 次翻倍到 1024。指数长得快、对数长得慢，同一枚硬币的两面。","en":"An exponent is shorthand for repeated multiplication: 2¹⁰ is ten 2s multiplied; a logarithm asks the reverse — how many multiplications reach this number — so log₂1024 = 10, because ten doublings reach 1024. Exponents grow fast, logarithms grow slowly: two sides of one coin."},"formula":"log_b(bˣ) = x","source":"../math/algebra/exponents-logarithms/#step2","lessons":[{"slug":"exponents-logarithms","step":2,"category":"math","stage":"senior","primary":true}],"aliases":{"zh":["指数函数","对数函数","自然常数e","e 是什么"],"en":["exponential function","exponential","logarithm","number e"]}},
"expected-value":{"description":{"zh":"期望 E = Σ p·x 是长期平均的公平价：判断下注是否值得（净期望 = E − 价格）、E[X+Y] = E[X] + E[Y] 的可加性、保险为什么用较差的期望换取更小的波动，以及圣彼得堡悖论。风险中性的独立重复模型。","en":"The expected value E = Σ p·x is the fair price of a long-run average: whether a bet is worth it (net expectation = E − price), the additivity E[X+Y] = E[X] + E[Y], why insurance trades a worse expectation for less variation, and the St. Petersburg paradox. A risk-neutral model of independent repeated plays."},"formula":"E = Σ p·x","source":"../probability/basics/expected-value/#step1","lessons":[{"slug":"expected-value","step":1,"category":"probability","stage":"senior","primary":true}],"note":"Edges use existing atlas nodes probability, montecarlo and variance.","aliases":{"zh":["期望值","数学期望","赌场为什么总赢","庄家优势"],"en":["expected value","why the house always wins","house edge","expectation"]}},
"harmonic-function":{"description":{"zh":"在一个调里，和弦按所在的音阶级数扮演不同角色：主功能（I）站稳、前属功能（IV、ii）做准备、属功能（V）制造张力；终止式就是这些角色的衔接，V–I 像句号，IV–I 温和落地，停在 V 上像逗号。","en":"Within a key, chords play roles set by their scale degree: tonic (I) feels settled, predominant (IV, ii) prepares, dominant (V) builds tension; a cadence links these roles — V–I like a full stop, IV–I a gentle landing, stopping on V like a comma."},"source":"../math/applied/music-theory/#step2","lessons":[{"slug":"music-theory","step":2,"category":"math","stage":"senior","primary":true}],"aliases":{"zh":["和弦功能","终止式","主和弦 属和弦 下属和弦","罗马数字和弦标记","音阶级数","为什么 V–I 听起来像结束","和声入门"],"en":["chord function","cadence","tonic, dominant and subdominant chords","Roman numeral analysis","scale degrees","why does V–I sound final","introduction to harmony"]}},
"integral":{"description":{"zh":"定积分累加带符号的贡献。在正向时间区间，速度积分是位移，速率积分才是路程；位置差与位置坐标不同。","en":"A definite integral accumulates signed contributions. Over forward time, integrating velocity gives displacement; integrating speed gives distance. Position difference is distinct from a position coordinate."},"formula":"∫aᵇ v dt = x(b) − x(a)","source":"../math/calculus/integral/#step2","lessons":[{"slug":"integral","step":2,"category":"math","stage":"senior","primary":true}],"aliases":{"zh":["积分","定积分"],"en":["integral","integration","area under the curve"]}},
"isomers":{"description":{"zh":"同样的原子、不同的连接就是不同的分子：比如正丁烷与异丁烷原子数相同，骨架一直一拐，沸点就从约 0°C 变到约 −12°C；醇与醚、顺反异构也是同理，形状不同，性质就不同，计数时要用规范形式去重。不含环与手性。","en":"The same atoms with different connections are different molecules: n-butane and isobutane share a formula, but a straight versus branched skeleton moves the boiling point from about 0 °C to about −12 °C. Alcohols versus ethers and cis–trans isomers work the same way — different shape, different properties — so counting uses canonical forms to avoid duplicates. No rings or chirality."},"formula":"CₙH₂ₙ₊₂: 1, 1, 1, 2, 3, 5, 9, 18 skeletons","source":"../chemistry/matter/isomers/#step1","lessons":[{"slug":"isomers","step":1,"category":"chemistry","stage":"senior","primary":true}],"note":"group math is the closest of the five atlas groups (graphs and counting); the page is chemistry"},
"molecular-shapes":{"description":{"zh":"价层电子对互相排斥，N 个区域排成最散的队形，孤对更胖、挤得更开：水分子两个孤对把成键对挤弯成约 104.5°，形状不对称所以有极性；二氧化碳没有孤对、排成直线，对称抵消就没有极性。教学简化模型，不含轨道。","en":"Valence electron pairs repel, so N regions spread out as far as possible, with lone pairs fatter and pushing harder: water's two lone pairs bend its bonds to about 104.5°, and the lopsided shape gives polarity, while carbon dioxide has no lone pairs, lines up straight, and its symmetry cancels polarity. A teaching simplification without orbitals."},"formula":"E = Σ qᵢqⱼ/r","source":"../chemistry/matter/molecular-shapes/#step0","lessons":[{"slug":"molecular-shapes","step":0,"category":"chemistry","stage":"senior","primary":true}],"note":"group math is the closest of the five atlas groups; the page is chemistry geometry","aliases":{"zh":["化学键","共价键"],"en":["chemical bond","covalent bond"]}},
"musical-intervals":{"description":{"zh":"两个音之间的距离用半音数来量，在十二平均律里每升一个半音频率乘 2^(1/12)，升 12 个半音正好翻倍成高八度；所以听起来等距的音程，在频率上是等比而不是等差。","en":"The distance between two notes is counted in semitones; in twelve-tone equal temperament each semitone multiplies the frequency by 2^(1/12), so 12 semitones exactly double it — an octave; intervals that sound evenly spaced are equal ratios, not equal differences, in frequency."},"formula":"f = f₀ · 2^(n/12)","source":"../math/applied/music-theory/#step0","lessons":[{"slug":"music-theory","step":0,"category":"math","stage":"senior","primary":true}],"aliases":{"zh":["音程","八度","半音 全音","十二平均律","为什么高八度听起来像同一个音","纯五度","音高和频率","音阶","音阶是怎么来的","为什么有些音放在一起好听","协和音程"],"en":["musical interval","octave","semitone and whole tone","twelve-tone equal temperament","why does an octave sound like the same note","perfect fifth","pitch and frequency","musical scale","musical scales","scales","why do some notes sound good together","consonance"]}},
"periodic-trends":{"description":{"zh":"前四周期主族元素的原子半径、电离能、电负性热图与趋势：同周期从左往右，核电荷递增、电子层不变，有效核电荷把外层电子拉得更紧，原子半径就越往右越小——这就是斯莱特有效核电荷的解释；含例外，不含过渡金属。","en":"Atomic radius, ionisation energy and electronegativity heat maps and trends for main-group elements of periods 1–4: across a period, nuclear charge rises while shells stay put, so the Slater effective nuclear charge pulls outer electrons tighter and radii shrink left to right — that pull is the explanation. Includes exceptions, no transition metals."},"formula":"r ∝ n*²/Zeff","source":"../chemistry/matter/periodic-trends/#step2","lessons":[{"slug":"periodic-trends","step":2,"category":"chemistry","stage":"senior","primary":true}],"note":"group math is the closest of the five atlas groups; the page is chemistry","aliases":{"zh":["元素周期表","周期表"],"en":["periodic table","how to read the periodic table"]}},
"sequences-series":{"description":{"zh":"等差数列的通项与倒序相加求和（把两列拼成长方形），等比数列的棋盘麦粒式爆炸增长、部分和与无穷项的极限（|r|<1），以及线性与指数累计的反超月份；最后辨认数列类型。实数数列的纯数学模型。","en":"The general term of arithmetic sequences and the add-it-backwards sum (two rows form a rectangle), the chessboard-style explosive growth of geometric sequences, partial sums and the infinite limit for |r|<1, the month where exponential accumulation overtakes linear, and finally recognising sequence types. A pure-maths model of real-number sequences."},"formula":"Sₙ = n(a₁+aₙ)/2,  Sₙ = a₁(1−rⁿ)/(1−r)","source":"../math/algebra/sequences-series/#step1","lessons":[{"slug":"sequences-series","step":1,"category":"math","stage":"senior","primary":true}]},
"determinant":{"description":{"zh":"矩阵把单位正方形变成一个平行四边形，行列式 det A = ad − bc 就是它的有符号面积：绝对值是面积放大的倍数，负号表示翻面；det = 0 时平面被压成一条线，信息丢失，矩阵没有逆。","en":"A matrix turns the unit square into a parallelogram, and the determinant det A = ad − bc is its signed area: the size is the area scale factor and a minus sign means the plane is flipped; when det = 0 the plane is squashed onto a line, information is lost and the matrix has no inverse."},"formula":"det A = ad − bc","source":"../math/linear-algebra/linear-transform/#step2","lessons":[{"slug":"linear-transform","step":2,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["行列式","行列式的几何意义","行列式为 0 是什么意思","可逆矩阵","奇异矩阵","逆矩阵"],"en":["determinant","geometric meaning of the determinant","what does a zero determinant mean","invertible matrix","singular matrix","inverse matrix"]}},
"eigen":{"description":{"zh":"对称矩阵总有一组互相垂直的特殊方向：作用上去只拉长或压短、不转方向——这就是特征向量，拉伸比例 λ 是特征值，它们是变换的“脊梁方向”。（一般实矩阵未必有实特征方向：旋转就没有。）","en":"A symmetric matrix always has a set of mutually perpendicular special directions: acting on them only stretches or shrinks, never turns — those are eigenvectors, with stretch factor λ the eigenvalue; they are the transformation's spine directions. (A general real matrix need not have real eigendirections: a rotation has none.)"},"formula":"Av = λv","source":"../math/linear-algebra/eigenvectors/#step1","lessons":[{"slug":"eigenvectors","step":1,"category":"math","stage":"university","primary":true}]},
"embeddings":{"description":{"zh":"把词表示成一列数，用余弦衡量相似，用向量加减做类比，并从共现统计里学出向量。前三步用手工玩具特征，第四步是原始计数，不是真实训练。","en":"Represent words as lists of numbers, measure similarity with cosine, solve analogies with vector arithmetic, and learn vectors from co-occurrence statistics. Early steps use hand-set toy features and step 4 uses raw counts, not real training."},"formula":"cos(A,B) = A·B / (|A||B|)","source":"../computing/ml/embeddings/#step1","lessons":[{"slug":"embeddings","step":1,"category":"computing","stage":"university","primary":true}]},
"externalities":{"description":{"zh":"当部分成本落在第三方身上，市场按私人成本多生产，无谓损失 = ½·e·(Q_m − Q*)；税率等于边际外部损害的庇古税使福利最大；公地被过度使用；科斯：无成本谈判下权利归谁不影响效率。线性模型，损害为常数。","en":"When part of the cost falls on a third party the market over-produces, with deadweight loss ½·e·(Q_m − Q*); a Pigouvian tax equal to the marginal damage maximises welfare; commons are overused; Coase: with costless bargaining who holds the right does not change efficiency. A linear model with constant damage."},"formula":"DWL = ½ · e · (Q_m − Q*)","source":"../math/applied/externalities/#step3","lessons":[{"slug":"externalities","step":3,"category":"math","stage":"university","primary":true}],"note":"No economics group in the atlas; group set to math as supply-demand does on the site. Edge sources are existing site pages merged separately.","aliases":{"zh":["外部性","庇古税"],"en":["externality","pigouvian tax"]}},
"laplace":{"description":{"zh":"傅里叶只问“含哪些频率”，拉普拉斯多问一句“信号在长大还是衰减”：用 e^{st} 去试探，s 的实部管增长衰减、虚部管振荡；收敛域就是这套试探成立的 s 范围——极点的位置直接告诉你系统会不会发散。","en":"Fourier asks only 'which frequencies are in it'; Laplace asks one more question, 'is the signal growing or decaying': probe with e^{st}, where the real part of s governs growth or decay and the imaginary part governs oscillation; the region of convergence is the range of s where this probing holds — and pole positions say directly whether the system blows up."},"formula":"s = σ + iω","source":"../signal/transforms/laplace/#step1","lessons":[{"slug":"laplace","step":1,"category":"signal","stage":"university","primary":true}]},
"limit-epsilon-delta":{"description":{"zh":"“x 无限接近 a 时 f(x) 趋于 L”被写成一场博弈：对方随便给一个误差 ε > 0，你总能找到一个 δ > 0，使 x 离 a 不到 δ（但不等于 a）时 f(x) 离 L 不到 ε；找不到这样的 δ，极限就不存在。","en":"“f(x) approaches L as x gets arbitrarily close to a” is written as a game: whatever error ε > 0 the opponent names, you can always find δ > 0 so that whenever x is within δ of a (but not equal to it), f(x) is within ε of L; if no such δ exists, the limit does not exist."},"formula":"∀ε>0 ∃δ>0: 0<|x−a|<δ ⇒ |f(x)−L|<ε","source":"../math/calculus/limits-epsilon/#step1","lessons":[{"slug":"limits-epsilon","step":1,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["极限","ε-δ 语言","极限的定义","ε-N 定义","数列极限","极限不存在","无限接近是什么意思","epsilon delta"],"en":["limit","epsilon-delta definition","definition of a limit","epsilon-N definition","limit of a sequence","limit does not exist","what does arbitrarily close mean","epsilon delta proof"]}},
"mandelbrot-set":{"description":{"zh":"从 z = 0 出发反复计算 z ← z² + c，平面上的每个点 c 只有两种命运：永远留在半径 2 的圆内（属于集合）或迟早逃逸；按命运给所有点上色，一行算术就长出一条怎么放大细节都不枯竭的分形边界。","en":"Starting from z = 0 and repeating z ← z² + c, every point c of the plane has one of two fates: it stays inside the circle of radius 2 forever (it belongs to the set) or sooner or later escapes; colouring all points by their fate grows, from one line of arithmetic, a fractal boundary whose detail never runs out however far you zoom."},"formula":"z ← z² + c","source":"../math/calculus/mandelbrot/#step1","lessons":[{"slug":"mandelbrot","step":1,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["曼德博集合","分形","朱利亚集","自相似","无限放大的图形","曼德布罗特","z² + c"],"en":["Mandelbrot set","fractal","Julia set","self-similarity","infinite zoom","mandelbrot","z squared plus c"]}},
"matrix-transform":{"description":{"zh":"一个 2×2 矩阵只需说清两根基向量 (1, 0) 和 (0, 1) 各去了哪里（就是它的两列），平面上每个点、整张网格就都跟着确定；先做 A 再做 B 写作 BA，一般 AB ≠ BA，顺序会改变结果。","en":"A 2×2 matrix only has to say where the two basis vectors (1, 0) and (0, 1) go — its two columns — and every point and the whole grid of the plane follow; doing A then B is written BA, and in general AB ≠ BA, so the order changes the result."},"formula":"A(x, y) = x·a₁ + y·a₂","source":"../math/linear-algebra/linear-transform/#step0","lessons":[{"slug":"linear-transform","step":0,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["矩阵是什么","线性变换","矩阵乘法","矩阵乘法为什么不能交换","基向量","矩阵的列","旋转矩阵"],"en":["what is a matrix","linear transformation","matrix multiplication","why is matrix multiplication not commutative","basis vectors","columns of a matrix","rotation matrix"]}},
"newton-method":{"description":{"zh":"用切线与横轴的交点作下一个猜测，观察正确位数大约翻倍的收敛，以及切线水平、循环、起点决定终点等失败情形，并与二分法对比。单变量光滑函数、双精度浮点。","en":"Take where the tangent meets the x-axis as the next guess; see the correct digits roughly double, then the failures (flat tangent, cycles, start-dependent destinations) and a comparison with bisection. One variable, smooth functions, double precision."},"formula":"x_{n+1} = x_n − f(x_n)/f′(x_n)","source":"../math/calculus/newton-method/#step2","lessons":[{"slug":"newton-method","step":2,"category":"math","stage":"university","primary":true}],"note":"binary-search is a page slug, not an atlas node; if the coordinator has no atlas node for it the second edge may be dropped."},
"pagerank":{"description":{"zh":"把「重要」定义成随机冲浪者长期停留的概率：可以模拟，也可以用幂迭代算出；阻尼系数和一条新链接怎样改变排名。8 页玩具网络。","en":"Define “important” as the long-run probability of a random surfer: it can be simulated or computed by power iteration; how the damping factor and one new link change the ranking. An 8-page toy network."},"formula":"r = (1−d)/N · 1 + d·M·r","source":"../computing/algorithms/pagerank/#step2","lessons":[{"slug":"pagerank","step":2,"category":"computing","stage":"university","primary":true}],"aliases":{"zh":["搜索引擎","搜索引擎是怎么排名的","网页排名","谷歌搜索"],"en":["search engine","how does google search work","google search","page rank"]}},
"rsa-encryption":{"description":{"zh":"从“质数相乘易、分解难”出发，用模算术、欧拉定理与扩展欧几里得算法造出公钥和私钥，演示加密解密对所有明文成立，在浏览器里真实运行试除法看窃听者的成本，并估算现实密钥长度。教科书版 RSA：小质数、无填充，不能用于真实保密。","en":"Starting from “multiplying primes is easy, factoring is hard”, build public and private keys with modular arithmetic, Euler’s theorem and the extended Euclidean algorithm, show encryption and decryption working for every plaintext, run trial division for real to see the eavesdropper’s cost, and estimate real key lengths. Textbook RSA with tiny primes and no padding — not for real secrecy."},"formula":"c = m^e mod n,  m = c^d mod n,  e·d ≡ 1 (mod φ(n))","source":"../computing/systems/rsa-encryption/#step3","lessons":[{"slug":"rsa-encryption","step":3,"category":"computing","stage":"university","primary":true}],"note":"hashing and exp-log are page slugs; remap to atlas nodes if available.","aliases":{"zh":["公钥私钥","公钥加密","非对称加密","加密是怎么工作的","模运算","费马小定理"],"en":["public key cryptography","public-key encryption","asymmetric encryption","modular arithmetic","fermat's little theorem","clock arithmetic"]}},
"sine":{"description":{"zh":"匀速绕圆运动的坐标随时间周期变化。振幅、频率和相位分别决定大小、快慢和起点。","en":"Coordinates of uniform circular motion vary periodically. Amplitude, frequency and phase set the size, rate and starting point."},"formula":"A sin(2πft + φ)","source":"../math/geometry/trigonometry/#step3","help":{"title":{"zh":"相位、弧度与每秒周期数","en":"Phase, radians and cycles per second"},"body":{"zh":"θ 表示一周期内的进度。弧度是弧长除以半径，一周为 2π rad。f 是每秒周期数（Hz），T 是一周期的秒数，ω=2πf 是每秒变化的弧度数（rad/s），T=1/f。正弦式中的 φ 设定起始相位。","en":"θ marks progress through a cycle. A radian angle is arc length divided by radius; one turn is2π rad. f counts cycles per second (Hz), T is seconds per cycle, and ω=2πf measures radians per second; T=1/f. In the sine formula, φ sets the starting phase."},"sources":[{"href":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/7-1-angles","label":{"zh":"OpenStax · 弧度定义 ↗","en":"OpenStax · radian definition ↗"}},{"href":"https://openstax.org/books/university-physics-volume-1/pages/15-1-simple-harmonic-motion","label":{"zh":"OpenStax · 周期与角频率 ↗","en":"OpenStax · period & angular frequency ↗"}}]},"lessons":[{"slug":"trigonometry","step":3,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["正弦","余弦","正弦和余弦","sin cos","三角函数 sin cos"],"en":["sine and cosine","sin and cos","sine","cosine"]}},
"taylor-series":{"description":{"zh":"用多项式在一点附近逐项贴合 sin x、eˣ、1/(1−x)、ln(1+x)；系数来自各阶导数；收敛半径内加项变准、半径外越加越差；用 eˣ 级数实际算数，并与傅里叶的整体逼近对照。一元实函数模型。","en":"Match sin x, eˣ, 1/(1−x) and ln(1+x) term by term with polynomials near a point; the coefficients come from derivatives; inside the radius of convergence more terms help, outside they hurt; compute with the eˣ series and contrast with Fourier’s global approximation. A one-real-variable model."},"formula":"f(x) ≈ Σ f⁽ᵏ⁾(a)/k! · (x − a)ᵏ","source":"../math/calculus/taylor-series/#step2","lessons":[{"slug":"taylor-series","step":2,"category":"math","stage":"university","primary":true}],"aliases":{"zh":["泰勒展开","泰勒公式"],"en":["taylor expansion"]}},
"unit-circle":{"description":{"zh":"半径为 1 的圆：转过的角度 θ 落在圆上哪一点，它的横坐标就是 cos θ、纵坐标就是 sin θ——转一圈，两个坐标此起彼伏画出正弦余弦；钟面、月相都是它的影子。","en":"A circle of radius one: wherever the turned angle θ lands on the circle, its horizontal coordinate is cos θ and its vertical coordinate sin θ — one full turn draws sine and cosine rising and falling against each other; clock faces and moon phases are its shadows."},"formula":"(cos θ, sin θ)","source":"../math/geometry/trigonometry/#step1","lessons":[{"slug":"trigonometry","step":1,"category":"math","stage":"university","primary":true}]},
"vectors":{"description":{"zh":"向量是一组有顺序的数；矩阵把输入向量变为输出向量，并保持加法和数乘。","en":"A vector is an ordered collection of numbers. A matrix maps vectors while preserving addition and scalar multiplication."},"formula":"v ↦ Av","source":"../math/linear-algebra/eigenvectors/#step1","lessons":[{"slug":"eigenvectors","step":1,"category":"math","stage":"university","primary":true},{"slug":"vectors","step":1,"category":"math","stage":"senior","primary":false}]}
}});
